SUBJECTS = [
    ("Banking Awareness", "Banking Awareness"),
    ("Reasoning", "Reasoning"),
    ("Computer Aptitude", "Computer Aptitude"),
    ("Quantitative Aptitude", "Quantitative Aptitude"),
    ("Data Interpretation", "Data Interpretation"),
    ("English", "English"),
    ("General / Economy", "General / Economy"),
]

class HomeScreen(Screen):
    def on_enter(self):
        self.clear_widgets()
        root = BoxLayout(orientation="vertical", padding=16, spacing=9)
        root.add_widget(Label(text="[b]BANKING EXAM PREP[/b]", markup=True, font_size="27sp", size_hint_y=None, height=65))
        root.add_widget(Label(text="Practice MCQ • Mock Test • Score", font_size="16sp", size_hint_y=None, height=35))

        for label, mode in SUBJECTS:
            count = len([q for q in QUESTIONS if q["subject"] == mode])
            btn = Button(text=f"{label}  ({count})", font_size="16sp", size_hint_y=None, height=48)
            btn.bind(on_release=lambda b, m=mode: self.start_test(m))
            root.add_widget(btn)

        mock = Button(text="FULL MOCK TEST  (50)", font_size="17sp", size_hint_y=None, height=52)
        mock.bind(on_release=lambda b: self.start_test("FULL"))
        root.add_widget(mock)

        history = Button(text="SCORE HISTORY", font_size="15sp", size_hint_y=None, height=44)
        history.bind(on_release=lambda b: self.show_history())
        root.add_widget(history)
        root.add_widget(Label(text=f"{len(QUESTIONS)} questions included", font_size="13sp"))
        self.add_widget(root)

    def start_test(self, mode):
        quiz = self.manager.get_screen("quiz")
        quiz.start_test(mode)
        self.manager.current = "quiz"

    def show_history(self):
        self.manager.get_screen("history").refresh()
        self.manager.current = "history"

class QuizScreen(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.questions=[]; self.index=0; self.score=0; self.correct=0; self.wrong=0
        self.selected=None; self.time_left=60; self.timer_event=None; self.mode=""

    def start_test(self, mode):
        if self.timer_event: self.timer_event.cancel()
        self.mode=mode
        pool=QUESTIONS[:]
        if mode != "FULL": pool=[q for q in pool if q["subject"]==mode]
        random.shuffle(pool)
        self.questions=pool[:50 if mode=="FULL" else min(20,len(pool))]
        self.index=0; self.score=0; self.correct=0; self.wrong=0
        self.show_question()

    def show_question(self):
        self.clear_widgets(); self.selected=None; self.time_left=60
        q=self.questions[self.index]
        root=BoxLayout(orientation="vertical", padding=14, spacing=8)
        top=BoxLayout(size_hint_y=None,height=42)
        top.add_widget(Label(text=f"Question {self.index+1}/{len(self.questions)}",font_size="17sp"))
        self.timer_label=Label(text="Time: 60s",font_size="17sp")
        top.add_widget(self.timer_label); root.add_widget(top)
        root.add_widget(Label(text=f"[b]{q['subject']}[/b]",markup=True,font_size="15sp",size_hint_y=None,height=32))
        scroll=ScrollView(size_hint_y=0.34)
        ql=Label(text=q["q"],font_size="20sp",halign="left",valign="middle",text_size=(380,None),size_hint_y=None,padding=(5,10))
        ql.bind(texture_size=lambda obj,val:setattr(obj,"height",max(90,val[1])))
        scroll.add_widget(ql); root.add_widget(scroll)
        self.option_buttons=[]
        for i,opt in enumerate(q["options"]):
            btn=Button(text=f"{chr(65+i)}. {opt}",font_size="16sp",size_hint_y=None,height=50)
            btn.bind(on_release=lambda b,n=i:self.select_option(n))
            self.option_buttons.append(btn); root.add_widget(btn)
        self.next_btn=Button(text="Next",font_size="17sp",size_hint_y=None,height=50,disabled=True)
        self.next_btn.bind(on_release=self.next_question); root.add_widget(self.next_btn)
        home=Button(text="Exit to Home",font_size="14sp",size_hint_y=None,height=40)
        home.bind(on_release=self.go_home); root.add_widget(home)
        self.add_widget(root)
        self.timer_event=Clock.schedule_interval(self.update_timer,1)

    def update_timer(self,dt):
        self.time_left-=1
        if hasattr(self,"timer_label"): self.timer_label.text=f"Time: {self.time_left}s"
        if self.time_left<=0: self.next_question(None)

    def select_option(self,n):
        if self.selected is not None: return
        self.selected=n; q=self.questions[self.index]
        if n==q["answer"]:
            self.score+=1; self.correct+=1; self.option_buttons[n].text += "  ✓ Correct"
        else:
            self.score-=0.25; self.wrong+=1
            self.option_buttons[n].text += "  ✗ Wrong"
            self.option_buttons[q["answer"]].text += "  ← Correct"
        self.next_btn.disabled=False

    def next_question(self,_):
        if self.timer_event: self.timer_event.cancel()
        if self.index+1 < len(self.questions):
            self.index+=1; self.show_question()
        else:
            result=self.manager.get_screen("result")
            result.show_result(self.mode,self.score,self.correct,self.wrong,len(self.questions))
            self.manager.current="result"

    def go_home(self,_):
        if self.timer_event: self.timer_event.cancel()
        self.manager.current="home"

class ResultScreen(Screen):
    def show_result(self,mode,score,correct,wrong,total):
        self.clear_widgets()
        accuracy=(correct/total*100) if total else 0
        store=JsonStore("score_history.json")
        old=store.get("tests")["items"] if store.exists("tests") else []
        old.append({"mode":mode,"score":round(score,2),"correct":correct,"wrong":wrong,"total":total,"accuracy":round(accuracy,1)})
        store.put("tests",items=old[-20:])
        root=BoxLayout(orientation="vertical",padding=25,spacing=14)
        root.add_widget(Label(text="[b]TEST COMPLETE[/b]",markup=True,font_size="29sp",size_hint_y=None,height=75))
        root.add_widget(Label(text=f"Score: {score:.2f}",font_size="27sp",size_hint_y=None,height=60))
        root.add_widget(Label(text=f"Correct: {correct}\nWrong: {wrong}\nTotal: {total}",font_size="20sp",size_hint_y=None,height=115))
        root.add_widget(Label(text=f"Accuracy: {accuracy:.1f}%",font_size="20sp",size_hint_y=None,height=50))
        again=Button(text="Take Another Test",font_size="17sp",size_hint_y=None,height=55)
        again.bind(on_release=lambda x:setattr(self.manager,"current","home")); root.add_widget(again)
        hist=Button(text="View Score History",font_size="16sp",size_hint_y=None,height=48)
        hist.bind(on_release=lambda x:self.view_history()); root.add_widget(hist)
        self.add_widget(root)
    def view_history(self):
        self.manager.get_screen("history").refresh(); self.manager.current="history"

class HistoryScreen(Screen):
    def refresh(self):
        self.clear_widgets()
        root=BoxLayout(orientation="vertical",padding=15,spacing=10)
        root.add_widget(Label(text="[b]SCORE HISTORY[/b]",markup=True,font_size="27sp",size_hint_y=None,height=60))
        store=JsonStore("score_history.json")
        items=store.get("tests")["items"] if store.exists("tests") else []
        if not items:
            root.add_widget(Label(text="No tests completed yet.",font_size="18sp"))
        else:
            scroll=ScrollView()
            box=BoxLayout(orientation="vertical",size_hint_y=None,spacing=7)
            box.bind(minimum_height=box.setter("height"))
            for i,item in enumerate(reversed(items),1):
                txt=f"{i}. {item['mode']}  | Score {item['score']} | {item['correct']}/{item['total']} | {item['accuracy']}%"
                box.add_widget(Label(text=txt,font_size="14sp",size_hint_y=None,height=38))
            scroll.add_widget(box); root.add_widget(scroll)
        back=Button(text="Back to Home",size_hint_y=None,height=48)
        back.bind(on_release=lambda x:setattr(self.manager,"current","home")); root.add_widget(back)
        self.add_widget(root)

class BankingExamApp(App):
    title="Banking Exam Prep"
    def build(self):
        sm=ScreenManager()
        sm.add_widget(HomeScreen(name="home"))
        sm.add_widget(QuizScreen(name="quiz"))
        sm.add_widget(ResultScreen(name="result"))
        sm.add_widget(HistoryScreen(name="history"))
        return sm

if __name__=="__main__":
    BankingExamApp().run()
